# SMART PLOT EXPLORER - interactive plots for a final Introduction to R lecture.
# Uses the plot-selection rules from page 9 of the prior visualization lecture.
# Run with shiny::runApp('app') from the project root.
# Only base R + shiny are needed to RUN the app; displayed ggplot2 recipes are illustrative.

library(shiny)
source('plot_logic.R', local = TRUE)
source('data_io.R', local = TRUE)

options(shiny.maxRequestSize = 5 * 1024^2)  # Teaching-scale CSV uploads: 5 MiB.

biomed <- read.csv(file.path('data', 'synthetic_biomed_samples.csv'),
                   stringsAsFactors = FALSE)
for (nm in c('treatment', 'sex', 'tissue', 'response')) biomed[[nm]] <- factor(biomed[[nm]])
biomed$treatment <- factor(biomed$treatment, levels = c('Control', 'Drug'))
flowers <- datasets::iris
built_in_datasets <- list('biomed' = biomed, 'iris' = flowers)

dataset_columns <- function(d) setdiff(names(d), 'sample_id')
variable_choices <- function(d, except = character(0)) {
  vars <- setdiff(dataset_columns(d), except)
  if (!length(vars)) return(character(0))
  labels <- vapply(vars, function(nm) sprintf('%s  (%s)', nm,
     if (is_numeric_variable(d[[nm]])) 'numerical' else 'categorical'), character(1))
  stats::setNames(vars, labels)
}
category_choices <- function(d, except = character(0)) {
  vars <- dataset_columns(d)
  vars <- vars[vapply(d[vars], is_categorical_variable, logical(1))]
  variable_choices(d, except = union(except, setdiff(dataset_columns(d), vars)))
}
default_columns <- function(d, source = 'uploaded') {
  vars <- dataset_columns(d)
  num <- vars[vapply(d[vars], is_numeric_variable, logical(1))]
  cat <- vars[vapply(d[vars], is_categorical_variable, logical(1))]
  if (identical(source, 'iris')) return(c('Petal.Length', 'Sepal.Length', 'Species'))
  if (identical(source, 'biomed')) return(c('treatment', 'gene_expression', 'sex'))
  x <- if (length(cat)) cat[1] else vars[1]
  y <- if (length(num) && !identical(num[1], x)) num[1] else if (length(setdiff(vars, x))) setdiff(vars, x)[1] else ''
  g <- setdiff(cat, c(x, y))
  c(x, y, if (length(g)) g[1] else '')
}

ui <- fluidPage(
  tags$head(tags$style(HTML('
    body {font-family: Arial, Helvetica, sans-serif; background: #ffffff; color: #24332e;}
    h2 {font-weight: 750; color: #205e4a; margin-top: 18px;}
    .leadtext {color: #4a6359; margin-bottom: 15px; font-size: 16px;}
    .well {background: #f5faf7; border: 1px solid #d6e6db; border-radius: 9px;}
    .rulecard {border-left: 5px solid #3ca36f; background: #f0f7f2; padding: 12px 14px;
      margin: 1px 0 15px; border-radius: 3px;}
    .plotpanel {border: 1px solid #e2e9e5; border-radius: 7px; padding: 5px 10px 0;}
    .small {font-size: 13px; color: #536b60;}
    .helptext {font-size: 12px; color: #627169; margin-top: -6px; margin-bottom: 14px;}
    details {margin-top: 12px; background: #f6f8f7; border: 1px solid #e3e8e5;
      border-radius: 7px; padding: 12px;}
    summary {cursor: pointer; font-weight: 700; color: #205e4a;}
    pre {font-size: 13px; white-space: pre-wrap; background: #ffffff;}
    .note {margin-top: 12px; color: #627169; font-size: 12px;}
    .btn-default {border-color: #85bca0; color: #205e4a; font-weight: 700;}
  '))),
  h2('Which plot should we use?'),
  p('Choose variables and let R suggest a visualization, using the rules from your earlier ggplot2 lecture.', class='leadtext'),
  sidebarLayout(
    sidebarPanel(width = 4,
      selectInput('dataset', '1. Choose a dataset',
        choices = c('Synthetic biomedical samples' = 'biomed',
                    'Iris flowers (earlier lecture)' = 'iris',
                    'My uploaded CSV' = 'uploaded')),
      fileInput('upload_csv', 'Or import your own CSV', accept = '.csv', multiple = FALSE,
                buttonLabel = 'Browse CSV', placeholder = 'No CSV selected'),
      p('Comma-separated; first row = column names. Max 5 MB. Use public or simulated data only.', class = 'helptext'),
      hr(),
      selectInput('x', '2. Variable 1: X axis / categories', choices = variable_choices(biomed),
                  selected = 'treatment'),
      selectInput('y', '3. Variable 2 (optional)',
                  choices = c('None - explore one variable' = OPTIONAL_NONE, variable_choices(biomed, 'treatment')),
                  selected = 'gene_expression', selectize = FALSE),
      selectInput('group', '4. Variable 3: group / colour (optional)',
                  choices = c('None' = OPTIONAL_NONE, category_choices(biomed, c('treatment', 'gene_expression'))),
                  selected = 'sex', selectize = FALSE),
      radioButtons('bar_layout', 'Bar chart layout (when relevant)',
                   choices = c('Side by side' = 'dodge', 'Stacked' = 'stack'),
                   selected = 'dodge', inline = TRUE),
      checkboxInput('show_points', 'Show observations on boxplots', value = TRUE),
      hr(),
      p('Tip: try two numerical variables with an optional categorical third variable.', class='small')
    ),
    mainPanel(width = 8,
      div(class = 'rulecard',
          strong(textOutput('chart_title', inline = TRUE)),
          p(textOutput('chart_reason', inline = TRUE), style = 'margin: 5px 0 0;')),
      div(class = 'plotpanel', plotOutput('chart', height = '390px')),
      p(textOutput('n_note', inline = TRUE), class = 'small'),
      downloadButton('save_plot', 'Download this plot (PNG)'),
      tags$details(
        tags$summary('Show the equivalent ggplot2 code'),
        p('Compare this with DATA + MAPPING + GEOMETRY from your earlier course.', class='small'),
        verbatimTextOutput('ggcode')
      )
    )
  ),
  p('Only the built-in example datasets are packaged with the app. An uploaded CSV is read for this session, not published with the app.', class='note')
)

server <- function(input, output, session) {
  upload_state <- reactive({
    if (is.null(input$upload_csv)) return(NULL)
    tryCatch(read_uploaded_csv(input$upload_csv$datapath, input$upload_csv$name,
                               input$upload_csv$size),
             error = function(e) structure(list(message = conditionMessage(e)), class='csv_import_error'))
  })
  # After importing a file, immediately switch to that dataset.
  observeEvent(input$upload_csv, {
    updateSelectInput(session, 'dataset', selected = 'uploaded')
  }, ignoreInit = TRUE)
  raw_data <- reactive({
    if (identical(input$dataset, 'uploaded')) return(upload_state())
    built_in_datasets[[input$dataset]]
  })
  dat <- reactive({
    d <- raw_data()
    validate(need(!is.null(d), 'Choose a CSV file above, or switch back to a built-in dataset.'))
    validate(need(!inherits(d, 'csv_import_error'),
                  if (inherits(d, 'csv_import_error')) paste('CSV error:', d$message) else TRUE))
    d
  })
  observeEvent(list(input$dataset, input$upload_csv), {
    d <- raw_data()
    if (is.null(d) || !is.data.frame(d)) {
      updateSelectInput(session, 'x', choices = character(0))
      updateSelectInput(session, 'y', choices = c('None - explore one variable' = OPTIONAL_NONE), selected = OPTIONAL_NONE)
      updateSelectInput(session, 'group', choices = c('None' = OPTIONAL_NONE), selected = OPTIONAL_NONE)
      return()
    }
    # Avoid transient combinations of columns from the old and new dataset.
    freezeReactiveValue(input, 'x')
    freezeReactiveValue(input, 'y')
    freezeReactiveValue(input, 'group')
    defaults <- default_columns(d, input$dataset)
    x0 <- defaults[1]; y0 <- encode_optional(defaults[2]); g0 <- encode_optional(defaults[3])
    updateSelectInput(session, 'x', choices = variable_choices(d), selected = x0)
    updateSelectInput(session, 'y', choices = c('None - explore one variable' = OPTIONAL_NONE,
                      variable_choices(d, except = x0)), selected = y0)
    updateSelectInput(session, 'group', choices = c('None' = OPTIONAL_NONE,
                      category_choices(d, except = c(x0, y0))), selected = g0)
  }, ignoreInit = TRUE)
  observeEvent(list(input$x, input$y), {
    d <- raw_data()
    if (!is.data.frame(d) || is.null(input$x) || !input$x %in% dataset_columns(d)) return()
    valid_y <- setdiff(dataset_columns(d), input$x)
    y <- decode_optional(input$y)
    current_y <- if (y %in% valid_y) y else ''
    updateSelectInput(session, 'y', choices = c('None - explore one variable' = OPTIONAL_NONE,
                      variable_choices(d, except = input$x)), selected = encode_optional(current_y))
    valid_group <- dataset_columns(d)
    valid_group <- valid_group[vapply(d[valid_group], is_categorical_variable, logical(1))]
    valid_group <- setdiff(valid_group, c(input$x, current_y))
    group <- decode_optional(input$group)
    current_group <- if (group %in% valid_group) group else ''
    updateSelectInput(session, 'group', choices = c('None' = OPTIONAL_NONE,
                      category_choices(d, except = c(input$x, current_y))), selected = encode_optional(current_group))
  }, ignoreInit = TRUE)
  plot_state <- reactive({
    d <- dat()
    req(!is.null(input$x), !is.null(input$y), !is.null(input$group))
    # Dropdowns use an explicit sentinel so 'None' remains selectable after a choice.
    y <- decode_optional(input$y)
    group <- decode_optional(input$group)
    validate(need(input$x %in% dataset_columns(d), 'Choose a first variable from this dataset.'))
    validate(need(!nzchar(y) || y %in% dataset_columns(d), 'Choose a valid second variable.'))
    validate(need(!nzchar(group) || group %in% dataset_columns(d), 'Choose a valid group.'))
    validate(need(!nzchar(y) || input$x != y, 'Select two different variables.'))
    validate(need(!nzchar(group) || !group %in% c(input$x, y),
                  'The optional group must be a different variable.'))
    info <- plot_recommendation(d, input$x, y, group)
    selected <- unique(c(info$x, info$y, info$group))
    selected <- selected[nzchar(selected)]
    usable <- stats::complete.cases(d[, selected, drop = FALSE])
    for (nm in selected) {
      if (is_numeric_variable(d[[nm]])) usable <- usable & is.finite(d[[nm]])
    }
    plotting <- droplevels(d[usable, , drop = FALSE])
    validate(need(nrow(plotting) > 0, 'No complete observations for this selection. Try different columns.'))
    cats <- selected[vapply(plotting[selected], is_categorical_variable, logical(1))]
    if (length(cats)) {
      counts <- vapply(plotting[cats], function(v) length(unique(v)), integer(1))
      validate(need(all(counts <= 12L),
                    'Too many categories for a readable plot (maximum 12 per categorical variable).'))
    }
    if (nzchar(info$group)) {
      validate(need(length(unique(plotting[[info$group]])) <= 5L,
                    'Choose a grouping variable with at most five levels.'))
    }
    if (info$kind == 'histogram') {
      validate(need(length(unique(plotting[[info$x]])) >= 2L,
                    'This numerical variable is constant; try another.'))
    }
    list(data = plotting, info = info, original_n = nrow(d), used_n = nrow(plotting))
  })
  output$chart_title <- renderText({ plot_state()$info$title })
  output$chart_reason <- renderText({ plot_state()$info$why })
  output$chart <- renderPlot({
    st <- plot_state()
    render_suggested_plot(st$data, st$info, input$bar_layout, input$show_points)
  }, res = 110)
  output$ggcode <- renderText({
    ggplot2_recipe(plot_state()$info, input$bar_layout, input$show_points)
  })
  output$n_note <- renderText({
    st <- plot_state()
    kind <- if (identical(input$dataset, 'iris')) 'flowers' else 'rows'
    sprintf('%d of %d %s shown after omitting missing values in selected columns.',
            st$used_n, st$original_n, kind)
  })
  output$save_plot <- downloadHandler(
    filename = function() {
      safe <- gsub('[^A-Za-z0-9_-]+', '_', input$x)
      paste0('smart_plot_', safe, '.png')
    },
    content = function(file) {
      st <- plot_state() # Same filtered data and mapping as the on-screen plot.
      grDevices::png(filename = file, width = 1600, height = 1000, res = 160)
      on.exit(grDevices::dev.off(), add = TRUE)
      render_suggested_plot(st$data, st$info, input$bar_layout, input$show_points)
    },
    contentType = 'image/png'
  )
}

shinyApp(ui = ui, server = server)

# CSV import for the teaching app. Source plot_logic.R first when testing.

read_uploaded_csv <- function(file_path, file_name, file_size = NA_real_) {
  if (!grepl('\\.csv$', file_name, ignore.case = TRUE))
    stop('Please choose a .csv file.')
  if (is.finite(file_size) && file_size > 5 * 1024^2)
    stop('The CSV is larger than the 5 MB teaching limit.')
  d <- utils::read.csv(file_path, stringsAsFactors = FALSE,
                       check.names = TRUE, strip.white = TRUE,
                       na.strings = c('', 'NA', 'N/A'), fileEncoding = 'UTF-8-BOM')
  if (!nrow(d) || !ncol(d)) stop('The CSV must contain a header and at least one data row.')
  if (nrow(d) > 100000L || ncol(d) > 40L)
    stop('For this demo, use at most 100,000 rows and 40 columns.')
  for (nm in names(d)) {
    if (is.character(d[[nm]])) d[[nm]] <- factor(d[[nm]])
    if (is.logical(d[[nm]])) d[[nm]] <- factor(d[[nm]])
  }
  good <- vapply(d, function(col) is_numeric_variable(col) || is_categorical_variable(col), logical(1))
  d <- d[, good, drop = FALSE]
  if (!ncol(d)) stop('There are no numerical or categorical variables in this CSV.')
  d
}

# Plot suggestions deliberately mirror page 9 of the supplied visualization lecture.
# All plotting uses base R for a small, portable shinylive/webR teaching demo.
# The app additionally shows the equivalent (illustrative) ggplot2 recipe.

# A real option value, not an empty-string selectize placeholder.  CSV column names
# are sanitized by read.csv(check.names=TRUE), so they cannot equal this sentinel.
OPTIONAL_NONE <- '@@NONE@@'

decode_optional <- function(value) {
  if (is.null(value) || length(value) != 1L || is.na(value) ||
      identical(value, OPTIONAL_NONE)) return('')
  as.character(value)
}
encode_optional <- function(value) {
  if (!nzchar(decode_optional(value))) OPTIONAL_NONE else as.character(value)
}

is_numeric_variable <- function(x) is.numeric(x) && !is.factor(x)
is_categorical_variable <- function(x) is.factor(x) || is.character(x)

plot_recommendation <- function(data, x, y = '', group = '') {
  if (!x %in% names(data)) stop('Choose a valid first variable.')
  if (nzchar(y) && (!y %in% names(data) || identical(y, x))) stop('Choose a different second variable.')
  if (nzchar(group) && (!group %in% names(data) || group %in% c(x, y) || !is_categorical_variable(data[[group]]))) {
    stop('The optional grouping variable must be a different categorical variable.')
  }
  a_num <- is_numeric_variable(data[[x]])
  b_num <- nzchar(y) && is_numeric_variable(data[[y]])
  a_cat <- is_categorical_variable(data[[x]])
  b_cat <- nzchar(y) && is_categorical_variable(data[[y]])
  if (!nzchar(y)) {
    if (a_num) return(list(kind = 'histogram', title = 'Histogram',
                           why = 'One numerical variable: inspect its distribution.', x = x, y = y, group = group))
    if (a_cat) return(list(kind = 'bar', title = 'Bar chart',
                           why = 'One categorical variable: compare category counts.', x = x, y = y, group = group))
  }
  if (a_num && b_num) return(list(kind = 'scatter', title = 'Scatterplot',
                                  why = 'Two numerical variables: inspect their relationship.', x = x, y = y, group = group))
  if (a_cat && b_num) return(list(kind = 'box', title = 'Boxplot + points',
                                  why = 'Numerical + categorical: compare distributions across groups.', x = x, y = y, group = group,
                                  category = x, measurement = y))
  if (a_num && b_cat) return(list(kind = 'box', title = 'Boxplot + points',
                                  why = 'Numerical + categorical: compare distributions across groups (axes arranged automatically).',
                                  x = x, y = y, group = group, category = y, measurement = x))
  if (a_cat && b_cat) return(list(kind = 'bar2', title = 'Grouped bar chart',
                                  why = 'Two categorical variables: compare counts within categories (an extension of page 9).',
                                  x = x, y = y, group = group))
  stop('This combination cannot be plotted with this teaching app.')
}

plot_colour <- function(n) rep(c('#2F9876', '#4F7ABF', '#D49339', '#B2689C', '#627C76'), length.out = n)
plot_label <- function(v) gsub('_', ' ', v, fixed = TRUE)

render_suggested_plot <- function(data, info, bar_layout = 'dodge', show_points = TRUE) {
  x <- info$x; y <- info$y; group <- info$group
  grouped <- nzchar(group)
  old <- par(no.readonly = TRUE)
  on.exit(par(old))
  par(bg = 'white', mar = c(5.1, 4.8, 1.9, 1.1), las = 1,
      cex.axis = 0.88, cex.lab = 1.04)
  if (info$kind == 'histogram') {
    v <- data[[x]]
    if (!grouped) {
      hist(v, breaks = 17, col = '#8BC9B0', border = 'white', main = '',
           xlab = plot_label(x), ylab = 'Count')
    } else {
      lev <- levels(factor(data[[group]]))
      par(mfrow = c(1, length(lev)), mar = c(5, 4.3, 2.8, 0.8))
      br <- pretty(range(v, finite = TRUE), n = 16)
      for (i in seq_along(lev)) {
        sub <- v[as.character(data[[group]]) == lev[i]]
        hist(sub, breaks = br, col = plot_colour(length(lev))[i], border = 'white',
             main = lev[i], xlab = plot_label(x), ylab = 'Count', xlim = range(br))
      }
    }
  } else if (info$kind == 'scatter') {
    xx <- data[[x]]; yy <- data[[y]]
    if (!grouped) {
      plot(xx, yy, pch = 16, cex = 0.95, col = grDevices::adjustcolor('#328E77', alpha.f = 0.69),
           xlab = plot_label(x), ylab = plot_label(y), main = '')
    } else {
      g <- factor(data[[group]]); lev <- levels(g); cols <- plot_colour(length(lev))
      sym <- rep(c(16, 17, 15, 18, 3), length.out = length(lev))
      plot(xx, yy, type = 'n', xlab = plot_label(x), ylab = plot_label(y), main = '')
      for (i in seq_along(lev)) {
        sel <- g == lev[i]
        points(xx[sel], yy[sel], pch = sym[i], cex = 0.95,
               col = grDevices::adjustcolor(cols[i], alpha.f = 0.74))
      }
      legend('topleft', legend = lev, pch = sym, col = cols, bty = 'n', cex = 0.82, title = plot_label(group))
    }
  } else if (info$kind == 'box') {
    cat <- factor(data[[info$category]]); value <- data[[info$measurement]]
    if (!grouped) {
      boxplot(value ~ cat, outline = FALSE, col = '#CFE9DD', border = '#417565',
              xlab = plot_label(info$category), ylab = plot_label(info$measurement),
              ylim = extendrange(value, f = .08), main = '')
      if (isTRUE(show_points)) {
        set.seed(124)
        stripchart(value ~ cat, method = 'jitter', jitter = .18, vertical = TRUE,
                   add = TRUE, pch = 16, cex = .62,
                   col = grDevices::adjustcolor('#274C43', alpha.f = .51))
      }
    } else {
      g <- factor(data[[group]]); catlev <- levels(cat); grplev <- levels(g)
      ncat <- length(catlev); ng <- length(grplev)
      positions <- outer((seq_len(ncat) - 1) * (ng + 1), seq_len(ng), '+')
      locations <- as.vector(t(positions))
      samples <- vector('list', ncat * ng)
      idx <- 1L
      for (k in seq_len(ncat)) for (j in seq_len(ng)) {
        samples[[idx]] <- value[cat == catlev[k] & g == grplev[j]]
        idx <- idx + 1L
      }
      cols <- plot_colour(ng)
      # Uploaded datasets may lack some category-by-group combinations.
      # Set a shared boxwex via pars: 'width' must have one entry PER box,
      # otherwise base R raises 'invalid boxplot widths' for grouped plots.
      nonempty <- lengths(samples) > 0L
      boxplot(samples[nonempty], at = locations[nonempty],
              names = rep('', sum(nonempty)), xaxt = 'n',
              outline = FALSE, pars = list(boxwex = .61),
              col = rep(cols, times = ncat)[nonempty],
              border = '#53635C', xlab = plot_label(info$category),
              ylab = plot_label(info$measurement), ylim = extendrange(value, f = .08),
              xlim = c(.2, max(locations) + .8), main = '')
      axis(1, at = rowMeans(positions), labels = catlev, tick = FALSE)
      if (isTRUE(show_points)) {
        set.seed(124)
        idx <- 1L
        for (k in seq_len(ncat)) for (j in seq_len(ng)) {
          vv <- samples[[idx]]
          if (length(vv)) points(jitter(rep(locations[idx], length(vv)), amount = .115), vv,
                                  pch = 16, cex = .46,
                                  col = grDevices::adjustcolor('#202A32', alpha.f = .46))
          idx <- idx + 1L
        }
      }
      legend('topleft', legend = grplev, fill = cols, bty = 'n', cex = .82, title = plot_label(group))
    }
  } else if (info$kind %in% c('bar', 'bar2')) {
    f1 <- factor(data[[x]])
    fill_name <- if (info$kind == 'bar2') y else group
    if (!nzchar(fill_name)) {
      tab <- table(f1)
      barplot(tab, col = '#78BAA1', border = NA,
              xlab = plot_label(x), ylab = 'Count', main = '')
    } else {
      f2 <- factor(data[[fill_name]])
      pane_name <- if (info$kind == 'bar2' && grouped) group else ''
      draw_bar <- function(which_rows, suffix = '') {
        tab <- table(f2[which_rows], f1[which_rows])
        cols <- plot_colour(nrow(tab))
        barplot(tab, beside = identical(bar_layout, 'dodge'),
                col = cols, border = NA, xlab = plot_label(x), ylab = 'Count',
                main = suffix, names.arg = colnames(tab))
        legend('topright', legend = rownames(tab), fill = cols,
               bty = 'n', cex = .72, title = plot_label(fill_name))
      }
      if (!nzchar(pane_name)) {
        draw_bar(rep(TRUE, nrow(data)))
      } else {
        f3 <- factor(data[[pane_name]])
        lev <- levels(f3)
        par(mfrow = c(1, length(lev)), mar = c(5.0, 3.8, 2.6, .7))
        for (t in lev) draw_bar(as.character(f3) == t, paste(plot_label(pane_name), t))
      }
    }
  }
  invisible(NULL)
}

ggplot2_recipe <- function(info, bar_layout = 'dodge', show_points = TRUE) {
  x <- info$x; y <- info$y; group <- info$group
  q <- function(v) paste0('`', v, '`')
  terms <- character(0)
  if (info$kind == 'histogram') {
    terms <- c(sprintf('ggplot(data, aes(x = %s))', q(x)), 'geom_histogram(bins = 17)')
    if (nzchar(group)) terms <- c(terms, sprintf('facet_wrap(~ %s)', q(group)))
  } else if (info$kind == 'scatter') {
    aes <- sprintf('x = %s, y = %s', q(x), q(y))
    if (nzchar(group)) aes <- paste0(aes, ', colour = ', q(group), ', shape = ', q(group))
    terms <- c(sprintf('ggplot(data, aes(%s))', aes), 'geom_point(size = 2, alpha = 0.75)')
  } else if (info$kind == 'box') {
    aes <- sprintf('x = %s, y = %s', q(info$category), q(info$measurement))
    if (nzchar(group)) aes <- paste0(aes, ', fill = ', q(group))
    terms <- c(sprintf('ggplot(data, aes(%s))', aes))
    if (nzchar(group)) {
      terms <- c(terms,
        'geom_boxplot(outlier.shape = NA, position = position_dodge2(width = 0.8))')
      if (isTRUE(show_points)) terms <- c(terms,
        sprintf(paste0('geom_point(aes(colour = %s),\n',
          '  position = position_jitterdodge(jitter.width = 0.08, dodge.width = 0.8),\n',
          '  alpha = 0.55, size = 1.3)'), q(group)))
    } else {
      terms <- c(terms, 'geom_boxplot(outlier.shape = NA)')
      if (isTRUE(show_points)) terms <- c(terms,
        'geom_jitter(width = 0.15, height = 0, alpha = 0.55)')
    }
  } else {
    fill <- if (info$kind == 'bar2') y else group
    aes <- sprintf('x = %s', q(x))
    if (nzchar(fill)) aes <- paste0(aes, ', fill = ', q(fill))
    terms <- c(sprintf('ggplot(data, aes(%s))', aes),
       sprintf('geom_bar(position = "%s")', if (nzchar(fill)) bar_layout else 'stack'))
    if (info$kind == 'bar2' && nzchar(group)) terms <- c(terms,
       sprintf('facet_wrap(~ %s)', q(group)))
  }
  paste(c(terms, 'theme_minimal()'), collapse = ' +\n  ')
}
